class Solution {
    public int roseGarden(int n, int[] nums, int k, int m) {
        if ((long) k * m > n) {
            return -1;
        }

        int low = Integer.MAX_VALUE;
        int high = Integer.MIN_VALUE;

        for (int day : nums) {
            low = Math.min(low, day);
            high = Math.max(high, day);
        }

        while (low < high) {
            int mid = low + (high - low) / 2;

            if (canMake(nums, k, m, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }

    private boolean canMake(int[] nums, int k, int needed, int day) {
        int consecutive = 0;
        int bouquets = 0;

        for (int bloomDay : nums) {
            if (bloomDay <= day) {
                consecutive++;
                if (consecutive == k) {
                    bouquets++;
                    consecutive = 0;
                }
            } else {
                consecutive = 0;
            }

            if (bouquets >= needed) {
                return true;
            }
        }

        return false;
    }
}
